import { coerceNumberProperty } from '@angular/cdk/coercion';
import {
  AfterViewInit,
  Directive,
  DoCheck,
  ElementRef,
  HostBinding,
  HostListener,
  inject,
  Input,
  NgZone,
} from '@angular/core';
import {
  QPlatformService,
  QSharedResizeObserverService,
} from '@questrade/allspark-angular-components/core/services';
import { injectDestroy, isPresent } from '@questrade/allspark-angular-components/core/utils';
import { takeUntil } from 'rxjs';

@Directive({
  selector: 'textarea[qTextareaAutosize][qTextarea], textarea[q-textarea-autosize][q-textarea]',
})
export class QTextareaAutosizeDirective implements AfterViewInit, DoCheck {
  @Input() get minRows(): number | null {
    return this._minRows;
  }
  set minRows(value: number | null) {
    this._minRows = coerceNumberProperty(value);
    this._setMinHeight();
  }

  @Input() get maxRows(): number | null {
    return this._maxRows;
  }
  set maxRows(value: number | null) {
    this._maxRows = coerceNumberProperty(value);
    this._setMaxHeight();
  }

  // Textarea elements that have the directive applied should have a single row by default.
  // Browsers show two rows by default and therefore this limits the minRows binding.
  @HostBinding('rows') hostRows = '1';

  @HostListener('input') onInput = (): void => this._noopInputHandler();

  private _previousValue = '';
  private _cachedLineHeight: number | null = null;
  private _previousMinRows: number | null = null;
  private _minRows: number | null = null;
  private _maxRows: number | null = null;
  private _maxHeight: number | null = null;
  private _minHeight: number | null = null;
  private _inputGap = 20;
  private readonly _destroy$ = injectDestroy();
  private readonly _textareaElement: HTMLTextAreaElement = inject(ElementRef).nativeElement;
  private readonly _ngZone = inject(NgZone);
  private readonly _platformService = inject(QPlatformService);
  private readonly _sharedResizeObserver = inject(QSharedResizeObserverService);

  ngAfterViewInit(): void {
    if (this._platformService.isBrowser) {
      this._resizeToFitContent();
      this._sharedResizeObserver
        .observe(this._textareaElement)
        ?.pipe(takeUntil(this._destroy$))
        .subscribe(() => this._resizeToFitContent(true));
    }
  }

  ngDoCheck(): void {
    if (this._platformService.isBrowser) {
      setTimeout(() => this._resizeToFitContent());
    }
  }

  _resizeToFitContent(force = false): void {
    this._cacheTextareaLineHeight();

    if (!this._cachedLineHeight) return;

    const textarea = this._textareaElement;
    const value = textarea.value;

    if (!force && this._minRows === this._previousMinRows && value === this._previousValue) {
      return;
    }

    const placeholderText = textarea.placeholder;

    textarea.style.height = 'auto';
    textarea.style.overflow = 'hidden';
    textarea.placeholder = '';

    let height =
      Math.round((textarea.scrollHeight - this._inputGap) / this._cachedLineHeight) *
        this._cachedLineHeight +
      this._inputGap;

    if (isPresent(this._maxHeight)) {
      height = Math.max(height, this._maxHeight);
    }
    if (isPresent(this._minHeight)) {
      height = Math.min(height, this._minHeight);
    }

    textarea.style.height = `${height}px`;
    textarea.style.overflow = 'auto';
    textarea.placeholder = placeholderText;

    if (typeof requestAnimationFrame !== 'undefined') {
      this._ngZone.runOutsideAngular(() =>
        requestAnimationFrame(() => {
          const { selectionStart, selectionEnd } = textarea;

          textarea.setSelectionRange(selectionStart, selectionEnd);
        }),
      );
    }

    this._previousValue = value;
    this._previousMinRows = this._minRows;
  }

  _cacheTextareaLineHeight(): void {
    if (isPresent(this._cachedLineHeight)) return;

    const textareaClone = this._textareaElement.cloneNode(false) as HTMLTextAreaElement;
    textareaClone.rows = 1;

    textareaClone.style.position = 'absolute';
    textareaClone.style.visibility = 'hidden';
    textareaClone.style.border = 'none';
    textareaClone.style.padding = '0';
    textareaClone.style.height = '';
    textareaClone.style.minHeight = '';
    textareaClone.style.maxHeight = '';
    textareaClone.style.overflow = 'hidden';

    this._textareaElement.parentNode?.appendChild(textareaClone);
    this._cachedLineHeight = textareaClone.clientHeight;
    textareaClone.remove();

    this._setMinHeight();
    this._setMaxHeight();
  }

  private _setMinHeight(): void {
    const minHeight =
      this._minRows && this._cachedLineHeight
        ? this._minRows * this._cachedLineHeight + this._inputGap
        : null;

    if (isPresent(minHeight)) {
      this._textareaElement.style.minHeight = `${minHeight}px`;
    }
  }

  private _setMaxHeight(): void {
    const maxHeight =
      this._maxRows && this._cachedLineHeight
        ? this._maxRows * this._cachedLineHeight + this._inputGap
        : null;
    if (isPresent(maxHeight)) {
      this._textareaElement.style.maxHeight = `${maxHeight}px`;
    }
  }

  private _noopInputHandler(): void {
    // noop handler that ensures we're running change detection on input events.
  }
}
