import { FocusMonitor } from '@angular/cdk/a11y';
import {
  AfterContentInit,
  booleanAttribute,
  Directive,
  DoCheck,
  ElementRef,
  HostBinding,
  HostListener,
  inject,
  Injector,
  Input,
  numberAttribute,
  OnInit,
  Renderer2,
} from '@angular/core';
import { FormGroupDirective, NgControl, NgForm } from '@angular/forms';
import { QSharedMutationObserverService } from '@questrade/allspark-angular-components/core/services';
import {
  ErrorState,
  injectDestroy,
  randomString,
} from '@questrade/allspark-angular-components/core/utils';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { takeUntil } from 'rxjs';

@Directive({
  selector: 'textarea[q-textarea], textarea[qTextarea]',
  providers: [{ provide: FormFieldControl, useExisting: QTextareaDirective }],
})
export class QTextareaDirective
  extends ErrorState
  implements OnInit, FormFieldControl, DoCheck, AfterContentInit
{
  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input({ alias: 'id' }) @HostBinding('attr.id') controlId = `q-textarea-${randomString()}`;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-textarea';

  @Input({ transform: booleanAttribute })
  @HostBinding('class.q-textarea-invalid')
  override errorState = false;

  @HostBinding('class') hostClass = 'q-textarea';

  @HostListener('input') onInput(): void {
    if (this._maxLength && !this.ngControl) {
      this._updateCounter();
    }
  }

  private _maxLength = 0;
  private _counterElement: HTMLSpanElement | null = null;
  private _containerElement: HTMLSpanElement | null = null;
  private readonly _destroy$ = injectDestroy();
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _textareaElement: HTMLTextAreaElement = inject(ElementRef).nativeElement;
  private readonly _injector = inject(Injector);
  private readonly _renderer = inject(Renderer2);
  private readonly _sharedMutationObserver = inject(QSharedMutationObserverService);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));
  }

  ngOnInit(): void {
    this._setComponentControl();
    this._focusMonitor.monitor(this._textareaElement);
    this._destroy$.onDestroy(() => this._focusMonitor.stopMonitoring(this._textareaElement));
  }

  ngAfterContentInit(): void {
    this._setCounterElement();
    this._listenForDisabledAndInvalidChanges();
    this._listenForControlChanges();
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();
    }
  }

  _setCounterElement(): void {
    const maxLength = numberAttribute(this._textareaElement.getAttribute('maxlength'), 0);
    this._maxLength = maxLength > 0 ? maxLength : 0;

    if (this._maxLength) {
      this._createCounterElements();
      this._updateCounter();
    }
  }

  private _createCounterElements(): void {
    this._containerElement = this._renderer.createElement('div');
    this._renderer.addClass(this._containerElement, 'q-textarea-container');

    const parent = this._renderer.parentNode(this._textareaElement);
    this._renderer.insertBefore(parent, this._containerElement, this._textareaElement);
    this._renderer.appendChild(this._containerElement, this._textareaElement);

    this._counterElement = this._renderer.createElement('span');
    this._renderer.addClass(this._counterElement, 'q-textarea-counter');
    this._renderer.appendChild(this._containerElement, this._counterElement);
  }

  private _updateCounter(): void {
    if (this._counterElement) {
      const valueLength = this._textareaElement.value.length;
      this._renderer.setProperty(
        this._counterElement,
        'textContent',
        `${valueLength}/${this._maxLength}`,
      );
    }
  }

  private _toggleCounterVisibility(isDisabledOrInvalid: boolean): void {
    if (this._counterElement) {
      this._renderer[isDisabledOrInvalid ? 'addClass' : 'removeClass'](
        this._counterElement,
        'q-textarea-counter-hidden',
      );
    }
  }

  private _listenForDisabledAndInvalidChanges(): void {
    this._sharedMutationObserver
      .observe(this._textareaElement, {
        characterData: true,
        subtree: true,
        attributes: true,
      })
      ?.pipe(takeUntil(this._destroy$))
      .subscribe((mutations: MutationRecord[]) => {
        mutations.forEach((mutation: MutationRecord) => {
          if (['disabled', 'class'].includes(mutation.attributeName || '')) {
            const mutationTarget = mutation.target as HTMLTextAreaElement;
            const isTargetDisabled = mutationTarget.hasAttribute('disabled');
            const isTargetInvalid = mutationTarget.classList.contains('q-textarea-invalid');
            this._toggleCounterVisibility(isTargetDisabled || isTargetInvalid);
          }

          if (mutation.type === 'characterData') {
            this._updateCounter();
          }
        });
      });
  }

  private _listenForControlChanges(): void {
    this.ngControl?.valueChanges
      ?.pipe(takeUntil(this._destroy$))
      .subscribe(() => this._updateCounter());
  }

  private _setComponentControl(): void {
    const injectedControl = this._injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }
}
